scaffold_files.content:
:root {
  --bg-primary: #0b0d17;
  --text-primary: #e0e6ed;
  --accent: #ff6b6b;
  --mars-red: #c1440e;
  --spacing-unit: 1rem;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  overflow-x: hidden;
}

#app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

section {
  min-height: 100vh;
  padding: calc(var(--spacing-unit) * 4);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

nav {
  display: flex;
  gap: var(--spacing-unit);
  padding: var(--spacing-unit);
  background: rgba(11, 13, 23, 0.9);
  position: fixed;
  top: 0;
  width: 100%;
  z-index: 100;
}

nav a {
  color: var(--text-primary);
  text-decoration: none;
  font-weight: 500;
}

